def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter, deque

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    comps = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = set()
            while q:
                y, x = q.popleft()
                cells.add((y, x))
                for ny, nx in ((y-1,x), (y+1,x), (y,x-1), (y,x+1)):
                    if (0 <= ny < h and 0 <= nx < w and
                        (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            comps.append((color, cells))

    by_color = {}
    for color, cells in comps:
        by_color.setdefault(color, []).append(cells)

    candidates = []
    for color, objects in by_color.items():
        if len(objects) < 2:
            continue
        objects.sort(key=lambda cells: min(r for r, c in cells))
        # Use the two largest components of this color as the repeated pattern.
        objects = sorted(objects, key=len, reverse=True)[:2]
        first, second = sorted(objects, key=lambda cells: min(r for r, c in cells))
        r1, c1 = min(r for r, c in first), min(c for r, c in first)
        r2, c2 = min(r for r, c in second), min(c for r, c in second)
        mask1 = {(r-r1, c-c1) for r, c in first}
        mask2 = {(r-r2, c-c2) for r, c in second}
        union = mask1 | mask2
        similarity = len(mask1 & mask2) / max(1, len(union))
        candidates.append((similarity, first, second, r1, c1, r2, c2))

    out = [row[:] for row in grid]
    if candidates:
        _, first, second, r1, c1, r2, c2 = max(candidates, key=lambda x: x[0])
        mask1 = {(r-r1, c-c1) for r, c in first}
        mask2 = {(r-r2, c-c2) for r, c in second}
        for dr, dc in mask1 - mask2:
            y, x = r2 + dr, c2 + dc
            if 0 <= y < h and 0 <= x < w and out[y][x] == bg:
                out[y][x] = 1

    return out
